def catalog_record(entry: tuple[str, ...]) -> dict[str, object]:
    slug, name, tamil_name, category, meal_type, ingredients, preparation, dietary = entry
    return {
        "food_slug": slug,
        "name": name,
        "tamil_name": tamil_name,
        "category": category,
        "meal_type": meal_type,
        "cuisine": "Tamil Nadu",
        "description": f"Traditional Tamil Nadu dish reference for {name}. Restaurant recipe and serving details require confirmation.",
        "ingredients": ingredients,
        "cooking_method": preparation,
        "food_type": "non-vegetarian" if dietary == "non-vegetarian" else "vegetarian" if dietary in {"vegetarian", "vegan_if_recipe_confirmed"} else dietary,
        "allergens": None,
        "calories": None,
        "protein": None,
        "carbs": None,
        "fat": None,
        "fiber": None,
        "sodium": None,
        "serving_size": None,
        "price": None,
        "image_url": None,
        "nutrition_status": "unavailable",
        "nutrition_source": None,
        "nutrition_confidence": None,
        "restaurant_name": "NutriOrder AI",
        "availability_status": "pending_confirmation",
        "dietary_verified": 0,
        "allergens_verified": 0,
        "catalog_status": "reference_pending_restaurant_confirmation",
    }
